// ─── File: JvmMemoryAreasDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.jvmmem;

import java.math.BigDecimal;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class JvmMemoryAreasDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MemoryReporter reporter = new MemoryReporter();
        reporter.report("startup");

        // HEAP: allocate many Account objects (Young gen Eden first).
        List<Account> accounts = new ArrayList<>();
        for (int i = 0; i < 100_000; i++) {
            accounts.add(new Account("SAV" + i, "holder" + i, new BigDecimal("1000")));
        }
        log.info(() -> "allocated " + accounts.size() + " accounts on the HEAP");
        reporter.report("after heap allocation");

        // STACK: recursion pushes a frame per call (bounded by -Xss).
        int depth = sumDepth(accounts.get(0), 500);
        log.info(() -> "stack recursion reached depth " + depth);

        // DIRECT / OFF-HEAP memory: a ByteBuffer outside the heap.
        ByteBuffer direct = ByteBuffer.allocateDirect(8 * 1024 * 1024); // 8 MB off-heap
        direct.putLong(0, 1_000_000L);
        log.info(() -> "allocated 8MB DIRECT buffer; first long = " + direct.getLong(0));
        reporter.report("after direct buffer");

        // Keep references alive so GC does not reclaim before reporting.
        log.fine(() -> "accounts size kept alive: " + accounts.size());
    }

    // Simple recursion to exercise the per-thread STACK.
    private static int sumDepth(Account a, int remaining) {
        if (remaining == 0) return 0;         // base case
        return 1 + sumDepth(a, remaining - 1); // each call = one stack frame
    }
}

// ─── Would be in Account.java (HEAP objects) ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
}

// ─── Would be in MemoryReporter.java (reads heap vs non-heap via MX beans) ───
class MemoryReporter {
    private static final Logger log = Logger.getLogger("BankLog");
    private final java.lang.management.MemoryMXBean mem =
            java.lang.management.ManagementFactory.getMemoryMXBean();

    void report(String phase) {
        java.lang.management.MemoryUsage heap = mem.getHeapMemoryUsage();      // Young + Old
        java.lang.management.MemoryUsage nonHeap = mem.getNonHeapMemoryUsage(); // Metaspace + Code Cache
        long heapMb = heap.getUsed() / (1024 * 1024);
        long nonHeapMb = nonHeap.getUsed() / (1024 * 1024);
        log.info(() -> "[" + phase + "] HEAP used=" + heapMb + "MB (max "
                + (heap.getMax() / (1024 * 1024)) + "MB), NON-HEAP used="
                + nonHeapMb + "MB (Metaspace + Code Cache)");
    }
}
